SELECT ul.usage_log_id, ul.request_id, ul.billing_session_id, ul.employee_id, ul.token_id, ul.channel_id, ul.model_id, ul.endpoint_type, ul.stream_flag, ul.prompt_tokens, ul.completion_tokens, ul.total_tokens, ul.input_cost, ul.output_cost, ul.total_cost, ul.preconsume_quota, ul.settled_quota, ul.upstream_status, ul.gateway_status, ul.latency_ms, ul.error_msg, ul.create_time, m.model_name, c.channel_name FROM t_ai_usage_log ul LEFT JOIN t_ai_model m ON ul.model_id = m.model_id LEFT JOIN t_ai_channel c ON ul.channel_id = c.channel_id
AND ul.employee_id = #{queryForm.employeeId}
AND ul.request_id = #{queryForm.requestId}
AND ul.model_id = #{queryForm.modelId}
AND ul.channel_id = #{queryForm.channelId}
AND ul.create_time >= #{queryForm.startTime}
AND ul.create_time <= #{queryForm.endTime}
ORDER BY ul.create_time DESC
